export const K4_KNOWN_PLAIN = (() => {
  const chars = Array<string>(K4_CIPHER.length).fill('');
  for (const crib of K4_CRIBS) {
    crib.plain.split('').forEach((char, index) => {
      chars[crib.start - 1 + index] = char;
    });
  }
  return chars;
})();

